/bin/bash -lc "find / -type f \\( -name pvpython -o -name paraview -o -name ttkPersistenceDiagramCmd \\) 2>/dev/null | head -40; find / -type d -iname '*paraview*' 2>/dev/null | head -30; python3 - <<'PY'
try:
 import vtk
 print('vtk',vtk.vtkVersion.GetVTKVersion())
except Exception as e: print('no vtk',e)
PY"

