try:
 import vtk
 print('vtk',vtk.vtkVersion.GetVTKVersion())
except Exception as e: print('no vtk',e)
PY"

/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
r=XMLImageDataReader(FileName=['/workspace/QMCPACK.vti'])
for cls in [TTKPersistenceDiagram, TTKTopologicalSimplificationByPersistence, TTKScalarFieldCriticalPoints, TTKMorseSmaleComplex]:
 f=cls(Input=r)
 print('\\n',cls.__name__)
 for p in f.ListProperties():
  if any(s in p.lower() for s in ('scalar','threshold','persistence','offset','input')): print(p,repr(getattr(f,p)))
PY"

